        println(-1)
        return
    }

    if (a[N - 2] > a[N - 1] && a[N - 1] != 0) {
        println("DOWN")
        return
    }
    if (a[N - 2] < a[N - 1] && a[N - 1] != 15) {
        println("UP")
        return
    }
    if (a[N - 1] == 0) {
        println("UP")
        return
    }
    if (a[N - 1] == 15) {
        println("DOWN")
        return
    }
}

